# 100 animaux — 10 par région
ANIMAUX = [
    # ── AFRIQUE (10) ──────────────────────────────────────────────────────────
    ("Lion",               "Panthera leo",            "Afrique", "Savane / Prairies tropicales", "Carnivore", "1,2 m",  "190 kg",  "12 ans", "Grand félin africain et redoutable prédateur des savanes, le lion vit en groupes sociaux appelés troupes ou prides, composés de plusieurs femelles, leurs petits, et un ou deux mâles dominants. Le mâle se distingue par son imposante crinière qui protège son cou lors des combats et signale sa vigueur aux femelles. Les lionnes assurent l'essentiel de la chasse en coopérant pour encercler leurs proies, tandis que le mâle défend le territoire. Symbole de puissance et de royauté dans de nombreuses cultures, le lion est aujourd'hui menacé par la perte d'habitat et les conflits avec les éleveurs.",                          "pictures/lion",               3),
    ("Éléphant d'Afrique", "Loxodonta africana",      "Afrique", "Savane / Prairies tropicales", "Herbivore", "3,3 m",  "5000 kg", "65 ans", "Plus grand mammifère terrestre au monde, l'éléphant d'Afrique impressionne par sa stature colossale et son intelligence remarquable. Il vit en troupeaux matriarcaux guidés par la femelle la plus âgée, qui mémorise les sources d'eau et les itinéraires de migration sur des dizaines d'années. Ses défenses en ivoire, prolongements de ses incisives, servent à déraciner les arbres, creuser le sol et se défendre. Sa trompe, organe polyvalent composé de plus de 40 000 muscles, lui permet de saisir des objets, boire, communiquer et sentir à grande distance. L'espèce est gravement menacée par le braconnage pour l'ivoire et la destruction de son habitat.",                  "pictures/elephant_afrique",   2),
    ("Girafe",             "Giraffa camelopardalis",  "Afrique", "Savane / Prairies tropicales", "Herbivore", "5,5 m",  "800 kg",  "25 ans", "Plus grand animal terrestre du monde, la girafe doit sa silhouette unique à son cou extraordinairement long, qui peut atteindre deux mètres à lui seul. Cet appendice lui permet d'atteindre les feuilles d'acacia situées hors de portée de tous les autres herbivores, réduisant ainsi la compétition alimentaire. Sa langue préhensile bleue-noire, longue de 45 cm, est parfaitement adaptée pour saisir les feuilles entre les épines. La girafe possède un cœur massif pesant jusqu'à 11 kg pour pomper le sang jusqu'à son cerveau. Malgré son allure paisible, elle peut tuer un lion adulte d'un coup de patte.",          "pictures/girafe",             2),
    ("Zèbre de Burchell",  "Equus quagga",            "Afrique", "Savane / Prairies tropicales", "Herbivore", "1,4 m",  "320 kg",  "20 ans", "Équidé emblématique des savanes africaines, le zèbre de Burchell est reconnaissable à ses rayures noires et blanches uniques, telles des empreintes digitales, propres à chaque individu. Ces rayures jouent plusieurs rôles : elles perturberaient la vision des prédateurs lors des mouvements de groupe, régulent peut-être la température corporelle, et réduisent les piqûres d'insectes vecteurs de maladies. Les zèbres vivent en grands troupeaux souvent mélangés à des gnous et des antilopes, renforçant la vigilance collective. Ils effectuent l'une des grandes migrations d'herbivores d'Afrique de l'Est, parcourant des centaines de kilomètres en quête d'herbe fraîche.",              "pictures/zebre_burchell",     2),
    ("Guépard",            "Acinonyx jubatus",        "Afrique", "Savane / Prairies tropicales", "Carnivore", "0,8 m",  "60 kg",   "12 ans", "Animal le plus rapide du monde sur terre, le guépard peut atteindre 110 km/h en seulement trois secondes, grâce à une morphologie entièrement dédiée à la vitesse : corps élancé, griffes semi-rétractiles offrant une adhérence optimale, et une colonne vertébrale extrêmement flexible qui agit comme un ressort géant. Contrairement aux autres grands félins, il chasse de jour, repérant ses proies à longue distance depuis un point en hauteur avant de les poursuivre en sprint. Après la course, il doit se reposer plusieurs minutes avant de manger, au risque de se faire voler sa proie par des lions ou des hyènes. Menacé par la perte d'habitat et le déclin génétique dû à une faible diversité génétique.",                   "pictures/guepard",            3),
    ("Hippopotame",        "Hippopotamus amphibius",  "Afrique", "Rivières",                     "Herbivore", "1,5 m",  "3000 kg", "40 ans", "Troisième plus lourd mammifère terrestre, l'hippopotame passe la majeure partie de la journée immergé dans les rivières et les lacs pour protéger sa peau sensible du soleil africain. Il sécrète un liquide rougeâtre naturel faisant office de crème solaire et d'antiseptique. Malgré son apparence placide et son régime herbivore, il est considéré comme l'un des animaux les plus dangereux d'Afrique, responsable de nombreuses morts humaines chaque année. La nuit, il sort de l'eau pour brouter l'herbe, pouvant parcourir plusieurs kilomètres. Ses canines, qui peuvent dépasser 50 cm, sont utilisées lors des combats territoriaux entre mâles qui peuvent être mortels.",                 "pictures/hippopotame",        2),
    ("Gorille des plaines","Gorilla gorilla",         "Afrique", "Forêt tropicale humide",       "Folivore",  "1,7 m",  "180 kg",  "35 ans", "Plus grand primate du monde, le gorille des plaines vit en groupes familiaux stables dirigés par un mâle dominant appelé dos argenté en raison de la coloration grise caractéristique qui apparaît sur son dos à maturité. Malgré son imposante musculature, le gorille est un animal paisible se nourrissant principalement de feuilles, fruits, tiges et racines. Il partage 98,3 % de son ADN avec l'être humain et est capable d'apprendre le langage des signes en captivité. Les groupes communiquent par vocalises, postures et expressions faciales élaborées. Très menacé par la déforestation, le braconnage et les maladies transmises par l'homme, il est classé espèce en danger critique.",           "pictures/gorille_plaines",    2),
    ("Crocodile du Nil",   "Crocodylus niloticus",    "Afrique", "Rivières",                     "Carnivore", "4,5 m",  "750 kg",  "70 ans", "L'un des plus grands reptiles du monde et redoutable prédateur embusqué, le crocodile du Nil attend patiemment ses proies au bord des fleuves africains, dissimulé sous la surface de l'eau. Ses mâchoires exercent la force de morsure la plus puissante du règne animal, capable de broyer des os, mais les muscles qui ouvrent les mâchoires sont si faibles qu'une simple bande élastique peut les maintenir fermées. Il est doté d'un métabolisme très lent qui lui permet de survivre plusieurs mois sans se nourrir. Étonnamment, les femelles sont des mères très attentionnées qui transportent leurs petits dans leur gueule pour les mettre à l'eau après l'éclosion.",                "pictures/crocodile_nil",      3),
    ("Autruche",           "Struthio camelus",        "Afrique", "Savane / Prairies tropicales", "Omnivore",  "2,5 m",  "130 kg",  "40 ans", "Plus grand et plus lourd oiseau du monde, l'autruche a troqué le vol contre des capacités terrestres exceptionnelles. Elle peut courir à plus de 70 km/h en vitesse de pointe et maintenir 50 km/h sur de longues distances, ce qui en fait l'oiseau le plus rapide sur terre. Ses pattes puissantes, terminées par deux doigts seulement, peuvent tuer un lion ou un humain d'un coup. Ses yeux, grands comme des balles de tennis, sont les plus volumineux de tous les animaux terrestres. À la différence de la légende populaire, l'autruche ne cache pas la tête dans le sable mais se couche au sol pour se dissimuler. Ses œufs, les plus grands du règne animal, pèsent jusqu'à 1,5 kg.",                       "pictures/autruche",           2),
    ("Phacochère",         "Phacochoerus africanus",  "Afrique", "Savane / Prairies tropicales", "Omnivore",  "0,7 m",  "80 kg",   "15 ans", "Suidé robuste et trapu des savanes africaines, le phacochère est immédiatement reconnaissable à ses défenses recourbées vers le haut et aux verrues proéminentes qui ornent son visage, servant à protéger les yeux lors des combats. Pour brouter, il se met caractéristiquement à genoux sur ses pattes avant calleuses. Il vit dans des terriers abandonnés par d'autres animaux, qu'il rejoint toujours en reculant pour faire face aux prédateurs à la sortie. Bien que principalement herbivore, il consomme également des insectes, des charognes et des petits animaux selon les opportunités. Sa vitesse de course, pouvant dépasser 50 km/h, lui permet souvent d'échapper aux lions et léopards.",         "pictures/phacochere",         2),

    # ── EUROPE (10) ───────────────────────────────────────────────────────────
    ("Renard roux",        "Vulpes vulpes",            "Europe", "Forêts",                       "Omnivore",  "0,6 m",  "6 kg",    "5 ans",  "Canidé le plus répandu du monde, le renard roux fait preuve d'une adaptabilité remarquable qui lui permet de coloniser aussi bien les forêts et campagnes européennes que les banlieues et même les centres-villes. Son régime omnivore très varié – rongeurs, lapins, oiseaux, fruits, insectes, déchets humains – explique en grande partie son succès écologique. Chasseur solitaire et nocturne, il utilise le champ magnétique terrestre pour localiser ses proies sous la neige avec une précision déconcertante. Ses oreilles mobiles captent les sons les plus ténus. La femelle, appelée renarde, élève ses petits dans un terrier qu'elle creuse ou récupère. Symbole de ruse et d'intelligence dans de nombreuses cultures européennes.",                        "pictures/renard_roux",        3),
    ("Loup gris",          "Canis lupus",              "Europe", "Forêts",                       "Carnivore", "0,8 m",  "45 kg",   "13 ans", "Ancêtre sauvage du chien domestique, le loup gris est un prédateur social vivant en meutes hiérarchisées, généralement composées d'un couple alpha reproducteur et de leur descendance. La meute chasse coopérativement des proies bien plus grandes qu'un loup seul ne pourrait maîtriser, comme les cerfs, élans et bisons. Ses hurlements, portant à plus de 10 km, servent à maintenir la cohésion du groupe et à délimiter le territoire. Exterminé sur la majeure partie de l'Europe au cours des siècles passés, il effectue un retour naturel remarquable depuis quelques décennies, notamment en France, Italie et Allemagne, suscitant d'âpres débats entre éleveurs et défenseurs de l'environnement.",               "pictures/loup_gris",          3),
    ("Ours brun",          "Ursus arctos",             "Europe", "Forêts",                       "Omnivore",  "1,1 m",  "300 kg",  "25 ans", "Plus grand carnivore terrestre d'Europe, l'ours brun est en réalité un omnivore opportuniste dont l'alimentation se compose à 70-80 % de végétaux : baies, fruits, racines, herbes, ainsi que de miel dont il est friand. Poisson, insectes, charognes et petits mammifères complètent son régime. À l'automne, il entre dans une phase d'hyperphagie intense pour accumuler des réserves graisseuses avant l'hibernation hivernale, pendant laquelle sa température corporelle et sa fréquence cardiaque s'abaissent considérablement. Les femelles mettent bas pendant ce sommeil hivernal. Bien que discret et évitant généralement l'homme, il peut devenir dangereux quand il est surpris ou que ses petits sont menacés.",                   "pictures/ours_brun",          3),
    ("Lynx boréal",        "Lynx lynx",                "Europe", "Forêts",                       "Carnivore", "0,7 m",  "25 kg",   "17 ans", "Félin le plus discret et le plus mystérieux des forêts européennes, le lynx boréal est un chasseur solitaire et nocturne dont la présence passe souvent inaperçue malgré son envergure impressionnante. Ses larges pattes emplumées fonctionnent comme des raquettes à neige, lui permettant de poursuivre ses proies en hiver. Ses touffes de poils sur les oreilles amplifient les sons et lui confèrent une ouïe exceptionnelle. Il chasse principalement le chevreuil et le lièvre variable, guettant patiemment depuis un point en hauteur avant de bondir sur sa proie. Après avoir été exterminé dans une grande partie de son aire de répartition, il a été réintroduit avec succès dans plusieurs pays européens.",              "pictures/lynx_boreal",        3),
    ("Cerf élaphe",        "Cervus elaphus",           "Europe", "Forêts",                       "Herbivore", "1,4 m",  "200 kg",  "20 ans", "Plus grand cervidé d'Europe continentale, le cerf élaphe est célèbre pour le brame spectaculaire qui retentit dans les forêts à l'automne, saison des amours où les mâles s'affrontent rugissements à l'appui pour conquérir les femelles. Leurs bois, attribut exclusif des mâles, sont des os vivants recouverts de velours qui tombent et repoussent chaque année, devenant plus complexes avec l'âge. Un vieux mâle peut porter une ramure dépassant 10 kg. Herbivore broutant herbes, feuilles, jeunes pousses et écorces, il joue un rôle écologique fondamental dans la régulation de la végétation forestière. Son cri caractéristique pendant le rut peut s'entendre à plusieurs kilomètres.",        "pictures/cerf_elaphe",        2),
    ("Sanglier",           "Sus scrofa",               "Europe", "Forêts",                       "Omnivore",  "0,9 m",  "100 kg",  "10 ans", "Ancêtre sauvage du cochon domestique, le sanglier est l'un des mammifères les plus répandus et les plus adaptables d'Europe. Son régime omnivore extrêmement varié – racines, glands, champignons, vers, insectes, petits mammifères, charognes – lui permet de coloniser des habitats très différents, des forêts de chênes aux zones périurbaines. Son groin musculeux et mobile, véritable outil de fouissage, lui permet de retourner le sol à la recherche de nourriture. Les femelles, appelées laies, élèvent leurs marcassins rayés en groupes familiaux protecteurs. Le mâle possède des défenses acérées qui peuvent infliger des blessures graves. Sa population est en forte expansion en Europe, générant des conflits avec les agriculteurs.",                     "pictures/sanglier",           2),
    ("Chamois",            "Rupicapra rupicapra",      "Europe", "Montagnes",                    "Herbivore", "0,8 m",  "40 kg",   "22 ans", "Capriné agile et sûr-pied des zones rocheuses de montagne, le chamois est un alpiniste hors pair capable de sauter 2 mètres en hauteur et 6 mètres en longueur, et de courir à 50 km/h sur les terrains les plus escarpés. Ses sabots sont dotés d'une bordure dure pour s'accrocher aux rochers et d'une semelle souple pour amortir et adhérer. En été, il colonise les alpages et les zones rocheuses à haute altitude ; en hiver, il redescend dans les forêts pour se protéger du froid et trouver de la nourriture. Ses petites cornes recourbées en crochet à l'extrémité lui servent lors des combats pour la hiérarchie sociale. La peau chamois, réputée pour sa douceur, était historiquement faite de sa peau.",                        "pictures/chamois",            2),
    ("Cigogne blanche",    "Ciconia ciconia",          "Europe", "Plaine",                       "Carnivore", "1,1 m",  "3,5 kg",  "20 ans", "Grand échassier migrateur et emblème du printemps en Europe, la cigogne blanche effectue chaque année un voyage extraordinaire de plusieurs milliers de kilomètres entre ses zones de nidification européennes et ses quartiers d'hiver en Afrique subsaharienne. Elle voyage en groupes en profitant des colonnes d'air chaud pour planer sans effort. Elle niche sur des grandes structures élevées – toits, clochers, pylônes – construisant un nid monumental réutilisé et agrandi chaque année. Carnivore généraliste, elle consomme grenouilles, lézards, insectes, petits rongeurs et parfois serpents. Dans de nombreuses cultures européennes, elle est associée à la naissance et portée chance.",        "pictures/cigogne_blanche",    3),
    ("Hérisson d'Europe",  "Erinaceus europaeus",      "Europe", "Forêts",                       "Insectivore","0,25 m","0,8 kg",  "5 ans",  "Petit mammifère nocturne reconnaissable à son manteau de 5 000 à 7 000 piquants creux en kératine, le hérisson d'Europe est l'un des animaux les plus familiers des jardins et haies européens. Lorsqu'il se sent menacé, il se roule en boule, exposant uniquement ses piquants, ce qui le protège efficacement de la plupart des prédateurs, à l'exception du blaireau qui parvient à le dérouler. Insectivore généraliste, il consomme une grande variété d'invertébrés, de limaces et d'escargots, ainsi qu'occasionnellement des œufs d'oiseaux. Il hiberne de novembre à mars, réduisant sa température corporelle à quelques degrés au-dessus de zéro. Malheureusement, ses populations déclinent rapidement en raison de la fragmentation des habitats et de la mort sur les routes.",             "pictures/herisson_europe",    2),
    ("Vipère aspic",       "Vipera aspis",             "Europe", "Forêts",                       "Carnivore", "0,7 m",  "0,2 kg",  "15 ans", "Seul serpent venimeux fréquent en France, la vipère aspic est un reptile discret qui fuit généralement avant d'être aperçue. Son museau légèrement retroussé, sa tête triangulaire et son dessin dorsal en zigzag permettent de la distinguer de la couleuvre inoffensive. Son venin hémotoxique, injecté par deux crochets rétractiles, sert à immobiliser ses proies – souris, lézards, petits oiseaux – et non à attaquer l'homme, qu'elle mord uniquement en cas de dérangement. Elle est ectotherme et régule sa température en se chauffant au soleil sur des pierres ou billes de bois. Elle hiberne sous terre pendant les mois froids et met bas des petits vivants au lieu de pondre des œufs. Les morsures humaines, rares, sont rarement mortelles.",         "pictures/vipere_aspic",       3),

    # ── ASIE (10) ─────────────────────────────────────────────────────────────
    ("Panda géant",        "Ailuropoda melanoleuca",   "Asie",   "Forêt tropicale humide",       "Folivore",  "1,5 m",  "100 kg",  "20 ans", "Symbole mondial de la conservation de la nature et emblème du WWF, le panda géant est un ours dont l'évolution a pris un tournant spectaculaire vers un régime quasi exclusivement composé de bambou, représentant 99 % de son alimentation. Il consacre jusqu'à 14 heures par jour à manger pour absorber suffisamment de nutriments d'une plante pourtant peu calorique. Son faux pouce, en réalité un os du carpe hypertrophié, lui permet de saisir les tiges de bambou avec précision. Malgré son appartenance aux carnivores, son système digestif reste mal adapté aux végétaux. Longtemps au bord de l'extinction, ses effectifs ont été partiellement redressés grâce à d'importants programmes de conservation chinois et internationaux.", "pictures/panda_geant",      2),
    ("Tigre du Bengale",   "Panthera tigris tigris",   "Asie",   "Forêt tropicale humide",       "Carnivore", "1,1 m",  "230 kg",  "15 ans", "Plus grand félin du monde et chasseur solitaire des jungles asiatiques, le tigre du Bengale est un prédateur au sommet de la chaîne alimentaire dont la force, l'agilité et la discrétion en font un chasseur redoutable. Ses rayures verticales orange et noires constituent un camouflage parfait dans la végétation dense, chaque individu possédant un patron unique. Il chasse à l'affût ou en approche rampante, bondissant sur des proies comme les cerfs, sangliers et gaurs, qu'il tue d'une morsure à la gorge. Excellent nageur, il apprécie l'eau pour se rafraîchir. Avec moins de 2 500 individus sauvages, il est classé espèce en danger, menacé par le braconnage pour ses os utilisés en médecine traditionnelle et la destruction de la forêt.", "pictures/tigre_bengale",      4),
    ("Yak",                "Bos grunniens",            "Asie",   "Montagnes",                    "Herbivore", "1,8 m",  "600 kg",  "20 ans", "Grand bovidé des hauts plateaux tibétains, le yak est parfaitement adapté aux conditions extrêmes de la haute altitude, évoluant couramment entre 3 000 et 6 000 mètres. Son sang contient une hémoglobine particulière qui fixe l'oxygène avec une efficacité supérieure à celle des bovins des plaines. Son épaisse fourrure à double couche – poils longs et laine dense – le protège de températures pouvant descendre à -40°C. Domestiqué depuis plus de 3 000 ans par les peuples tibétains et mongols, il est indispensable comme animal de bât, source de lait, de viande, de laine et de bouse combustible. Les populations sauvages, appelées drong, sont désormais classées vulnérables en raison du braconnage.",                            "pictures/yak",                2),
    ("Léopard des neiges", "Panthera uncia",           "Asie",   "Montagnes",                    "Carnivore", "0,6 m",  "55 kg",   "18 ans", "Surnommé le fantôme des montagnes, le léopard des neiges est l'un des félins les plus insaisissables et les moins observés au monde, vivant dans les zones rocheuses escarpées d'Asie centrale entre 3 000 et 5 500 mètres d'altitude. Sa fourrure épaisse aux rosettes grises lui offre un camouflage parfait sur les rochers enneigés. Sa longue queue touffue, presque aussi longue que son corps, lui sert de balancier pour les sauts et d'écharpe pour se protéger le visage du froid. Ses larges pattes agissent comme des raquettes à neige. Chasseur de bharals, markhors et cerfs, il peut tuer des proies trois fois plus lourdes que lui. Moins de 10 000 individus subsistent à l'état sauvage, menacés par la perte d'habitat et le braconnage.",            "pictures/leopard_neiges",     4),
    ("Macaque japonais",   "Macaca fuscata",           "Asie",   "Forêts",                       "Omnivore",  "0,6 m",  "12 kg",   "27 ans", "Primate le plus septentrional du monde après l'être humain, le macaque japonais, ou singe des neiges, survit dans des régions où la température peut descendre à -15°C grâce à une adaptation comportementale célèbre dans le monde entier : il se baigne dans les sources d'eau chaude géothermique pour maintenir sa température corporelle. Ce comportement, appris par une femelle dans les années 1960 et transmis culturellement au reste du groupe, illustre parfaitement les capacités d'apprentissage social de cette espèce. Les macaques vivent en groupes hiérarchisés complexes, où les relations sociales, les alliances et le rang social influencent l'accès aux ressources. Leur face rouge vif s'intensifie pendant la saison des amours.",       "pictures/macaque_japonais",   3),
    ("Panda roux",         "Ailurus fulgens",          "Asie",   "Forêts",                       "Folivore",  "0,6 m",  "5 kg",    "14 ans", "Petit mammifère arboricole roux et blanc d'une apparence évoquant à la fois le renard et le raton laveur, le panda roux est en réalité une espèce à part entière, seul représentant vivant de la famille des Ailuridae. Il vit dans les forêts de bambous tempérées des contreforts de l'Himalaya et du sud-ouest de la Chine, à des altitudes comprises entre 2 200 et 4 800 mètres. Comme le panda géant, il possède un pseudo-pouce qui l'aide à manipuler les tiges de bambou. Arboricole habile, il passe une grande partie de son temps dans les arbres et utilise sa queue touffue comme couverture lors des nuits froides. Son pelage roux offre un excellent camouflage parmi les mousses rouges et le lichen qui couvrent les rochers de son habitat.",              "pictures/panda_roux",         2),
    ("Éléphant d'Asie",    "Elephas maximus",          "Asie",   "Forêt tropicale humide",       "Herbivore", "2,8 m",  "4000 kg", "60 ans", "Plus grand mammifère terrestre d'Asie, l'éléphant d'Asie se distingue de son cousin africain par ses plus petites oreilles, son dos plus bombé, et ses défenses présentes principalement chez les mâles. Considéré depuis des millénaires comme animal sacré dans les cultures asiatiques, il joue un rôle central dans les cérémonies religieuses hindoues et bouddhistes. Domestiqué depuis plus de 4 000 ans, il a été utilisé à la guerre, dans les chantiers forestiers et lors des processions royales. Son intelligence est remarquable : il utilise des outils, reconnaît son reflet dans un miroir et fait preuve d'empathie envers ses congénères blessés ou morts.",  "pictures/elephant_asie",  2),
    ("Gavial du Gange",    "Gavialis gangeticus",      "Asie",   "Rivières",                     "Piscivore", "4,5 m",  "180 kg",  "60 ans", "Crocodilien aux mâchoires démesurément allongées et fines, le gavial du Gange est parfaitement spécialisé dans la pêche : ses 110 dents pointues et serrées lui permettent de saisir les poissons glissants avec une précision chirurgicale dans les eaux des grands fleuves indiens. Malgré sa taille imposante, il est pratiquement inoffensif pour l'homme en raison de la fragilité de ses mâchoires, incapables de mordre des proies volumineuses. Le mâle développe une protubérance bulbeuse à l'extrémité de son museau, appelée ghara, utilisée pour produire des sons d'accouplement et des bulles. Avec moins de 1 000 individus sauvages dans les rivières du nord de l'Inde et du Népal, il est l'un des reptiles les plus menacés de la planète.",    "pictures/gavial_gange",       3),
    ("Grues de Sibérie",   "Leucogeranus leucogeranus","Asie",   "Lacs / Étangs",                "Omnivore",  "1,4 m",  "8 kg",    "25 ans", "L'un des oiseaux migrateurs les plus menacés et les plus impressionnants d'Asie, la grue de Sibérie parcourt chaque année jusqu'à 5 000 km entre ses zones de nidification en Sibérie occidentale et ses quartiers d'hiver en Inde et en Chine. Entièrement blanche à l'exception des plumes primaires noires et du masque rouge vif encadrant son œil jaune d'or, elle se distingue par sa beauté saisissante. Elle vit dans les vastes zones humides où elle sonde la vase à la recherche de tubercules aquatiques, de racines et de petits animaux. Son cri puissant et mélodieux est produit grâce à une trachée enroulée sur elle-même. Avec moins de 4 000 individus subsistant dans la nature, son avenir est très incertain.",                      "pictures/grue_siberie",       2),
    ("Cobra royal",        "Ophiophagus hannah",       "Asie",   "Forêt tropicale humide",       "Carnivore", "4,0 m",  "9 kg",    "20 ans", "Plus long serpent venimeux du monde, le cobra royal peut atteindre 5,5 mètres et injecter suffisamment de venin neurotoxique pour tuer un éléphant adulte en quelques heures ou un être humain en moins de 30 minutes. Son impressionnant capuchon étalé, formé par la dilatation de ses côtes cervicales, est un avertissement visuel redoutable. Contrairement à la plupart des serpents, il est capable de se redresser au tiers de sa hauteur et de regarder un homme dans les yeux. Espèce ophiophage, il se nourrit principalement d'autres serpents, y compris d'autres cobras et pythons. Fait remarquable parmi les serpents, la femelle construit un nid de feuilles et de végétaux et le surveille activement jusqu'à l'éclosion des œufs.",   "pictures/cobra_royal",        3),

    # ── AMÉRIQUE DU NORD (10) ─────────────────────────────────────────────────
    ("Bison d'Amérique",   "Bison bison",              "Amérique du Nord", "Plaine",             "Herbivore", "2 m",    "900 kg",  "20 ans", "Grand herbivore emblématique des grandes plaines nord-américaines, le bison d'Amérique formait autrefois des troupeaux colossaux de plusieurs dizaines de millions d'individus qui façonnaient le paysage de la prairie. En broutant, en se roulant dans la poussière et en piétinant le sol, ils créaient des mares temporaires et des zones de végétation diversifiée essentielles à de nombreuses espèces. La chasse industrielle européenne du XIXe siècle l'a réduit à quelques centaines d'individus vers 1900, avant une lente remontée grâce aux programmes de conservation. Aujourd'hui environ 500 000 bisons vivent en Amérique du Nord, dont la plupart en élevage. Animal sacré pour de nombreuses nations amérindiennes, il a été désigné animal national des États-Unis en 2016.",                        "pictures/bison_amerique",     2),
    ("Grizzly",            "Ursus arctos horribilis",  "Amérique du Nord", "Forêts",             "Omnivore",  "1,2 m",  "360 kg",  "25 ans", "Sous-espèce d'ours brun parmi les plus imposantes du monde, le grizzly est un omnivore puissant dont la bosse musculaire caractéristique sur les épaules alimente ses pattes avant massives, capables de déterrer des racines et de retourner d'énormes rochers. Son régime alimentaire est d'une grande diversité : baies, fruits, racines, insectes, rongeurs, charognes et surtout saumons qu'il pêche spectaculairement dans les rapides lors de la remontée estivale. Cette pêche frénétique constitue une hyperphagie préparatoire à l'hibernation hivernale pendant laquelle il peut perdre jusqu'à un tiers de son poids. Malgré sa réputation, le grizzly est généralement craintif envers l'homme et n'attaque que s'il est surpris, blessé ou si ses petits sont menacés.",   "pictures/grizzly",            3),
    ("Coyote",             "Canis latrans",            "Amérique du Nord", "Plaine",             "Omnivore",  "0,6 m",  "15 kg",   "14 ans", "Canidé opportuniste et extraordinairement adaptable, le coyote est l'un des rares grands prédateurs nord-américains à avoir étendu son aire de répartition au cours du XXe siècle malgré des décennies de persécution intensive. Il a colonisé les villes et banlieues de toute l'Amérique du Nord, s'adaptant à des régimes alimentaires très variés incluant rongeurs, lapins, fruits, insectes, déchets et même animaux domestiques. Son hurlement mélancolique, mêlé d'aboiements et de glapissements, est l'une des voix emblématiques de la nuit américaine. Il vit seul, en couple ou en petits groupes familiaux selon la disponibilité des ressources. Personnage central de la mythologie de nombreuses nations amérindiennes, il est souvent dépeint comme un esprit rusé et farceur.",     "pictures/coyote",             3),
    ("Puma",               "Puma concolor",            "Amérique du Nord", "Forêts",             "Carnivore", "0,8 m",  "80 kg",   "12 ans", "Grand félin solitaire possédant la plus large distribution géographique de tout mammifère terrestre du continent américain, le puma – aussi appelé couguar, lion de montagne ou panthère – s'étend depuis le Canada jusqu'au sud de l'Amérique du Sud, colonisant des habitats aussi variés que les forêts denses, les montagnes rocheuses, les déserts et les zones périurbaines. Prédateur au sommet de son écosystème, il régule les populations de cerfs et d'autres ongulés, jouant un rôle écologique fondamental. Contrairement aux autres grands félins, il est incapable de rugir, mais communique par cris, sifflements et ronronnements. Il peut réaliser des bonds de 6 mètres en hauteur et de 12 mètres en longueur. Discret et craintif envers l'homme, il est rarement aperçu.",     "pictures/puma",               3),
    ("Wapiti",             "Cervus canadensis",        "Amérique du Nord", "Forêts",             "Herbivore", "1,5 m",  "320 kg",  "20 ans", "Deuxième plus grand cervidé du monde après l'élan, le wapiti est reconnaissable à ses bois complexes et ramifiés que les mâles portent de la fin du printemps à l'hiver, avant de les perdre et de les faire repousser. Ces bois peuvent atteindre 1,5 mètre d'envergure et peser 18 kg. Durant le rut automnal, les mâles émettent un bramement puissant et flûté qui résonne dans les forêts et se livrent à des combats de bois spectaculaires pour la possession des femelles. Herbivore brouteur et brouteur selon les saisons, il migre verticalement en montagne l'été et descend dans les vallées à l'approche de l'hiver. Animal sacré pour de nombreuses nations amérindiennes des Plaines, il joue un rôle important dans les écosystèmes forestiers comme proie du puma et du loup.",                      "pictures/wapiti",             2),
    ("Mouffette rayée",    "Mephitis mephitis",        "Amérique du Nord", "Forêts",             "Omnivore",  "0,3 m",  "3 kg",    "7 ans",  "Petit mammifère nord-américain appartenant à la famille des mustélidés, la mouffette rayée est célèbre dans le monde entier pour son mécanisme de défense spectaculaire : elle projette avec une précision chirurgicale, jusqu'à 5 mètres de distance, un liquide sulfuré sécrété par ses glandes anales. Cette odeur nauséabonde, à base de thiols soufrés, est presque impossible à éliminer et peut même provoquer des irritations oculaires temporaires. Avant de pulvériser, elle prévient par plusieurs signaux d'avertissement : piétinements, soulèvement de la queue et renversement du corps. Omnivore opportuniste, elle consomme insectes, petits rongeurs, fruits, baies et œufs. Sa fourrure noire et blanche est elle-même un signal d'avertissement aposématique mémorisé par les prédateurs.",       "pictures/mouffette_rayee",   2),
    ("Aigle à tête blanche","Haliaeetus leucocephalus","Amérique du Nord", "Forêts",             "Carnivore", "0,9 m",  "6 kg",    "20 ans", "Symbole national des États-Unis depuis 1782 et l'un des oiseaux les plus emblématiques du monde, l'aigle à tête blanche est un grand rapace piscivore dont la tête et la queue blanches contrastant avec le corps brun sombre ne s'acquièrent qu'à l'âge de 4 à 5 ans. Sa vue est 4 à 8 fois plus perçante que celle de l'homme, lui permettant de repérer un poisson sous la surface de l'eau à plus de 1 km de distance. Il plonge les serres en avant pour saisir sa proie à la surface sans s'immerger. Son nid, appelé aire, est le plus grand de tous les oiseaux nord-américains et peut peser plusieurs tonnes après des années d'agrandissement. Quasi éteint dans les années 1970 à cause du DDT, il a remarquablement récupéré grâce aux protections mises en place.",        "pictures/aigle_tete_blanche", 4),
    ("Alligator américain","Alligator mississippiensis","Amérique du Nord","Marais / Mangroves", "Carnivore", "3,5 m",  "360 kg",  "50 ans", "Grand reptile emblématique des zones humides du sud-est des États-Unis, l'alligator américain est un rescapé de l'ère des dinosaures dont la morphologie n'a pratiquement pas changé depuis 37 millions d'années. Il joue un rôle écologique crucial en tant qu'ingénieur de l'écosystème : en creusant des terriers et des mares au fond des marais, il crée des refuges d'eau permanente vitaux pour des dizaines d'espèces en période de sécheresse. Sa force de morsure est l'une des plus puissantes mesurées chez tout animal vivant. La femelle surveille activement son nid de végétaux en décomposition et transporte ses petits dans sa gueule jusqu'à l'eau. Au bord de l'extinction dans les années 1960, il a spectaculairement récupéré grâce à des mesures de protection strictes.",         "pictures/alligator_americain",3),
    ("Bison des bois",     "Bison bison athabascae",   "Amérique du Nord", "Forêts",             "Herbivore", "2,2 m",  "1000 kg", "20 ans", "Plus grande sous-espèce de bison et plus grand ongulé sauvage d'Amérique du Nord, le bison des bois diffère de son cousin des plaines par sa stature encore plus massive, ses cornes plus longues et sa bosse antérieure plus proéminente. Il est adapté à la vie dans les vastes forêts boréales et les prairies marécageuses du nord du Canada et de l'Alaska. Comme le bison des plaines, il a failli disparaître au début du XXe siècle, réduit à quelques dizaines d'individus, avant une lente et difficile reconstitution grâce aux parcs nationaux canadiens. Il joue un rôle écologique important en broutant et piétinant la végétation, créant des mares et des prairies au sein de la forêt. Son statut de conservation est actuellement classé menacé.",    "pictures/bison_bois",         2),
    ("Raton laveur",       "Procyon lotor",            "Amérique du Nord", "Forêts",             "Omnivore",  "0,4 m",  "8 kg",    "5 ans",  "Mammifère opportuniste reconnaissable à son masque facial noir évoquant un bandit et à sa queue annelée, le raton laveur est l'un des animaux sauvages les mieux adaptés à la vie urbaine. Ses pattes avant sont extraordinairement habiles, dotées de cinq doigts longs et sensibles capables de déverrouiller des poubelles, ouvrir des portes et manipuler des objets avec une dextérité surprenante. Son nom vient de son comportement de tremper et palper sa nourriture dans l'eau, ce qui n'est pas un lavage à proprement parler mais stimule ses terminaisons nerveuses. Omnivore généraliste consommant de tout, il s'est rapidement répandu en Europe après des introductions et évasions, devenant une espèce invasive préoccupante.",       "pictures/raton_laveur",       2),

    # ── AMÉRIQUE DU SUD (10) ──────────────────────────────────────────────────
    ("Jaguar",             "Panthera onca",            "Amérique du Sud", "Forêts",              "Carnivore", "1,8 m",  "100 kg",  "15 ans", "Plus grand félin du continent américain et troisième plus grand félin du monde après le tigre et le lion, le jaguar est un prédateur apex des forêts tropicales d'Amérique du Sud et centrale. Contrairement au léopard qu'il évoque visuellement, il est bien plus massif et robuste. Sa morsure est la plus puissante de tous les félins proportionnellement à sa taille : ses crocs percent directement le crâne de ses proies pour atteindre le cerveau, une technique de mise à mort unique dans le règne animal. Excellent nageur, il chasse volontiers dans l'eau et se nourrit de caïmans, tortues, capybaras, pécaris et cerfs. Vénéré comme divinité par les civilisations mayas et aztèques, il est aujourd'hui menacé par la déforestation amazonienne et le braconnage.",                   "pictures/jaguar",             4),
    ("Tapir du Brésil",    "Tapirus terrestris",       "Amérique du Sud", "Forêt tropicale humide","Herbivore","1,1 m", "250 kg",  "30 ans", "Plus grand mammifère terrestre d'Amérique du Sud, le tapir du Brésil est un survivant préhistorique dont la morphologie archaïque n'a guère évolué depuis des millions d'années. Sa petite trompe préhensile et mobile, prolongement du nez et de la lèvre supérieure, lui sert à saisir feuilles et fruits. Excellent nageur, il se réfugie volontiers dans l'eau pour échapper aux prédateurs comme le jaguar et pour se débarrasser des parasites. Il joue un rôle écologique fondamental de jardinier de la forêt : en dispersant les graines de nombreuses espèces végétales via ses excréments, il contribue à la régénération et à la diversité de la forêt tropicale. Espèce nocturne et solitaire, il emprunte souvent les mêmes sentiers, créant des pistes dans la végétation dense.",     "pictures/tapir_bresil",       2),
    ("Anaconda vert",      "Eunectes murinus",         "Amérique du Sud", "Marais / Mangroves",  "Carnivore", "6,0 m",  "100 kg",  "20 ans", "Plus grand serpent du monde en termes de masse et de diamètre – pouvant dépasser 100 kg et 30 cm de circonférence – l'anaconda vert est un constricteur aquatique des marécages, rivières et lacs de l'Amazonie. Il attend ses proies à l'affût, à demi-immergé dans l'eau, profitant de sa couleur vert olive pour se fondre dans la végétation. Il attrape sa victime – capybara, caïman, cerfs, pécaris – dans ses mâchoires puis enroule son corps puissant pour étouffer par constriction progressive avant de l'avaler entière. Ses mâchoires articulées peuvent s'écarter pour ingérer des proies plus larges que sa tête. La femelle est significativement plus grande que le mâle et donne naissance à des petits vivants pouvant être une vingtaine.",         "pictures/anaconda_vert",      3),
    ("Capybara",           "Hydrochoerus hydrochaeris","Amérique du Sud", "Rivières",            "Herbivore", "0,6 m",  "65 kg",   "10 ans", "Plus grand rongeur vivant au monde, le capybara est un animal semi-aquatique des berges de rivières et lacs d'Amérique du Sud. Ses yeux, narines et oreilles, placés haut sur la tête, lui permettent de rester presque totalement immergé tout en surveillant son environnement. Ses pattes légèrement palmées facilitent la nage dans laquelle il est très à l'aise, pouvant rester sous l'eau jusqu'à 5 minutes pour échapper aux prédateurs. Animal social par excellence, il vit en groupes de 10 à 30 individus avec une hiérarchie claire dominée par un mâle. Son comportement placide et sa sociabilité en font l'une des espèces les plus appréciées des zoos. Curieusement, d'autres espèces comme les oiseaux, les singes et même les caïmans sont régulièrement observés se reposant sur son dos sans qu'il ne réagisse.",             "pictures/capybara",           2),
    ("Condor des Andes",   "Vultur gryphus",           "Amérique du Sud", "Montagnes",           "Carnivore", "1,2 m",  "12 kg",   "70 ans", "Plus grand oiseau volant d'Amérique du Sud avec une envergure pouvant atteindre 3,3 mètres, le condor des Andes est un charognard majestueux qui plane sans effort pendant des heures sur les courants ascendants des Andes, scrutant le sol à la recherche de carcasses d'animaux morts. Sa tête et son cou nus lui permettent d'introduire sa tête dans les carcasses sans se salir les plumes. Son bec puissant est capable de déchirer la peau la plus épaisse. Il joue un rôle sanitaire fondamental en nettoyant les paysages andins de la matière organique en décomposition. Avec une espérance de vie dépassant 70 ans et une maturité sexuelle tardive, il se reproduit très lentement – un seul œuf par an au mieux. Vénéré par les peuples andins, il reste menacé par l'empoisonnement et la persécution.",     "pictures/condor_andes",       4),
    ("Paresseux à 3 doigts","Bradypus tridactylus",   "Amérique du Sud", "Forêt tropicale humide","Folivore", "0,6 m",  "4 kg",    "30 ans", "Mammifère arboricole spécialisé dans un mode de vie à l'économie d'énergie poussé à l'extrême, le paresseux à trois doigts est l'un des animaux les plus lents de la planète, ne se déplaçant qu'à environ 125 mètres par heure en canopée. Son régime de feuilles d'une valeur nutritive et calorique très faible oblige son métabolisme à fonctionner à vitesse réduite, avec une température corporelle basse et variable. Il descend de son arbre seulement une fois par semaine pour déféquer au sol, s'exposant dangereusement aux prédateurs. Sa fourrure est recouverte d'algues microscopiques qui lui donnent une teinte verdâtre, camouflage idéal dans la canopée. Suspendu par ses griffes recourbées, il peut rester en position inversée même après la mort.",            "pictures/paresseux_trois_doigts",  2),
    ("Piranha rouge",      "Pygocentrus nattereri",    "Amérique du Sud", "Rivières",            "Carnivore", "0,3 m",  "1 kg",    "10 ans", "Poisson carnivore des rivières d'Amazonie à la réputation redoutable, le piranha rouge est doté de dents triangulaires tranchantes comme des rasoirs et jointées comme celles d'une scie, capables de trancher chair et os en quelques secondes. Il chasse en bancs pouvant compter plusieurs centaines d'individus, ce qui amplifie l'efficacité collective de la prédation. Malgré son image de mangeur d'hommes véhiculée par les films hollywoodiens, les attaques mortelles sur des humains sont extrêmement rares et les piranhas sont généralement craintifs envers les grandes créatures. Ils jouent un rôle écologique important de nettoyeurs des rivières amazoniennes en consommant les cadavres d'animaux et les poissons malades.",      "pictures/piranha_rouge",      3),
    ("Lama",               "Lama glama",               "Amérique du Sud", "Montagnes",           "Herbivore", "1,2 m",  "130 kg",  "20 ans", "Camélidé domestiqué depuis au moins 4 000 ans par les peuples andins, le lama est l'animal de bât et de compagnie emblématique des hauts plateaux de la cordillère des Andes, capable de porter des charges allant jusqu'à 30 kg sur des terrains accidentés et à haute altitude. Son sang contient une hémoglobine spécialisée particulièrement efficace pour capter l'oxygène raréfié de la montagne. Herbivore frugal, il se contente de maigres pâturages d'altitude. Le lama est réputé pour son caractère indépendant et son comportement défensif consistant à cracher un fluide acide issu de son premier estomac sur ceux qui l'importunent. Ses poils sont transformés en fibres textiles, sa viande est consommée et ses excréments servent de combustible dans les régions dénuées d'arbres.",                        "pictures/lama",               2),
    ("Fourmilier géant",   "Myrmecophaga tridactyla",  "Amérique du Sud", "Savane / Prairies tropicales","Insectivore","1,2 m","35 kg","14 ans","Grand mammifère insectivore dont la morphologie est entièrement dédiée à l'exploitation des termitières et fourmilières, le fourmilier géant possède un museau tubulaire allongé, une langue filiforme pouvant s'étendre jusqu'à 60 cm et s'enduire de salive collante jusqu'à 150 fois par minute, et des griffes antérieures puissantes pour ouvrir les constructions d'insectes. Il peut consommer jusqu'à 35 000 fourmis et termites en une seule journée. Dépourvu de dents, il broie ses proies dans son estomac musculeux. Sa queue touffue, aussi longue que son corps, lui sert de couverture la nuit. Excellent nageur malgré son apparence peu aquatique. Menacé par la destruction de la savane brésilienne et les incendies, il est classé vulnérable.", "pictures/fourmilier_geant",   2),
    ("Toucan toco",        "Ramphastos toco",          "Amérique du Sud", "Forêt tropicale humide","Frugivore","0,6 m",  "0,7 kg",  "20 ans", "Plus grand et plus célèbre représentant de la famille des toucans, le toucan toco arbore un bec orange vif démesuré pouvant atteindre 20 cm, soit un tiers de la longueur totale de l'oiseau. Contrairement à l'apparence, ce bec est léger car constitué d'une structure creuse en kératine renforcée de travées osseuses. Il joue un rôle de thermorégulateur en laissant échapper la chaleur corporelle, mais aussi d'outil pour cueillir les fruits et les passer au fond du gosier, et de signal visuel lors de la parade nuptiale. Le toucan est un disperseur de graines fondamental dans les forêts tropicales d'Amérique du Sud. Son plumage noir, blanc et rouge vif en fait l'un des oiseaux les plus reconnaissables du monde et une icône des forêts amazoniennes.",           "pictures/toucan_toco",        2),

    # ── OCÉANIE (10) ──────────────────────────────────────────────────────────
    ("Kangourou roux",    "Macropus rufus",           "Océanie", "Plaine",                      "Herbivore", "1,8 m",  "85 kg",   "12 ans", "Plus grand marsupial et plus grand mammifère natif d'Australie, le kangourou roux est le symbole national du pays et figure sur son blason. Son mode de locomotion par bonds successifs pouvant atteindre 9 mètres en longueur et 3 mètres en hauteur est particulièrement économe en énergie à grande vitesse grâce aux tendons élastiques de ses pattes postérieures qui fonctionnent comme des ressorts. La femelle, dès sa naissance, abrite son jeune minuscule et prématuré de 2 cm dans sa poche marsupiale pendant 8 mois. Le mâle possède une musculature imposante et se bat avec ses pattes arrière et ses griffes pour établir la dominance.",                                   "pictures/kangourou_roux",    2),
    ("Koala",              "Phascolarctos cinereus",   "Océanie", "Forêts",                      "Folivore",  "0,8 m",  "12 kg",   "18 ans", "Marsupial arboricole emblématique d'Australie, le koala est l'un des rares mammifères au monde à se nourrir quasi exclusivement de feuilles d'eucalyptus, une plante toxique que son foie spécialisé détoxifie efficacement. Son régime très peu énergétique l'oblige à dormir jusqu'à 20 heures par jour pour conserver son énergie. Ses empreintes digitales sont presque indiscernables de celles de l'homme, une coïncidence remarquable. Sa poche marsupiale s'ouvre vers le bas et le jeune s'y accroche grâce à ses griffes développées. Le koala communique par grognements puissants et inattendus pour sa taille, le mâle produisant des beuglements à basse fréquence pour affirmer son territoire. Ses populations ont été drastiquement réduites par les incendies catastrophiques de 2019-2020 et les maladies, notamment la chlamydia.",          "pictures/koala",          2),
    ("Ornithorynque",      "Ornithorhynchus anatinus", "Océanie", "Rivières",                    "Carnivore", "0,4 m",  "2 kg",    "15 ans", "L'un des animaux les plus extraordinaires et énigmatiques du monde, l'ornithorynque est un mammifère ovipare – l'un des cinq seuls au monde – qui pond des œufs à coquille coriace tout en allaitant ses petits avec du lait sécrété à travers la peau. Son bec souple ressemblant à celui d'un canard est en réalité un organe sensoriel très sophistiqué détectant les champs électriques produits par les muscles de ses proies aquatiques, lui permettant de chasser les yeux, oreilles et narines fermés. Les mâles possèdent un ergot venimeux sur les pattes postérieures capable d'infliger une douleur intense. Sa découverte par les zoologistes européens au XVIIIe siècle fut tellement incroyable qu'ils soupçonnèrent d'abord une farce élaborée.",        "pictures/ornithorynque",      3),
    ("Wombat commun",      "Vombatus ursinus",         "Océanie", "Forêts",                      "Herbivore", "0,9 m",  "35 kg",   "15 ans", "Marsupial fouisseur trapu et robuste de l'Australie du Sud-Est, le wombat est connu pour deux particularités biologiques absolument uniques dans le règne animal : il est le seul mammifère à produire des excréments cubiques, ce qui lui permet de marquer son territoire sans que ceux-ci ne roulent. Sa poche marsupiale, contrairement à celle du kangourou, s'ouvre vers l'arrière pour éviter que la terre ne rentre lors des fouilles. Sa croupe est durcie par des plaques cartilagineuses qui lui permettent de bloquer l'entrée de son terrier avec son postérieur, protégeant efficacement ses petits des prédateurs. Ses terriers complexes peuvent atteindre 30 mètres de longueur et 2 mètres de profondeur, et servent de refuge thermique à de nombreuses autres espèces.",            "pictures/wombat_commun",      2),
    ("Diable de Tasmanie", "Sarcophilus harrisii",     "Océanie", "Forêts",                      "Carnivore", "0,3 m",  "12 kg",   "8 ans",  "Plus grand marsupial carnivore vivant depuis l'extinction du loup de Tasmanie, le diable de Tasmanie est réputé pour ses cris perçants et déchirants, ses grognements féroces et ses repas bruyants qu'il partage en groupes avec une agressivité impressionnante. Sa force de morsure, proportionnellement à sa taille, est parmi les plus puissantes de tous les mammifères, lui permettant de broyer os et cartilages. Charognard efficace, il contribue à nettoyer l'environnement de la matière organique en décomposition, réduisant les risques sanitaires. Une maladie faciale transmissible, le DFTD, un cancer contagieux extrêmement rare dans la nature, a décimé ses populations depuis les années 1990. Des programmes de réintroduction en Australie continentale visent à assurer sa survie à long terme.",                        "pictures/diable_tasmanie",    3),
    ("Casoar à casque",    "Casuarius casuarius",      "Océanie", "Forêt tropicale humide",      "Frugivore", "1,7 m",  "60 kg",   "20 ans", "Grand oiseau frugivore non-volant et parmi les plus dangereux du monde, le casoar à casque arbore une casque osseux orange et bleu sur la tête dont la fonction exacte reste débattue : amplification des sons basses fréquences, protection de la tête en forêt dense, ou signal social. Ses pattes sont armées de griffes intérieures de 12 cm capables d'éventrer un homme d'un coup de pied. Il est essentiel à la santé de la forêt tropicale de Nouvelle-Guinée et du nord de l'Australie, car il disperse les graines de nombreuses espèces d'arbres dont les fruits sont trop grands pour être ingérés par d'autres animaux. Solitaire et territorial, la femelle confie incubation et élevage des poussins au mâle après la ponte.",      "pictures/casoar_casque",      2),
    ("Kiwi brun",          "Apteryx australis",        "Océanie", "Forêts",                      "Insectivore","0,4 m", "2,5 kg",  "20 ans", "Oiseau nocturne sans ailes emblématique de la Nouvelle-Zélande, le kiwi est un être à part dans le monde aviaire : il possède des narines à l'extrémité de son long bec – unique chez les oiseaux – qui lui permettent de flairer vers de terre et invertébrés dans le sol à la manière d'un mammifère. Ses plumes ressemblent davantage à du poil. Il pond l'œuf le plus grand proportionnellement à sa taille de tous les oiseaux : un seul œuf peut représenter jusqu'à 20 % de son poids. Sa température corporelle est la plus basse de tout oiseau et proche de celle des mammifères. Il vit en couple monogame stable pendant des années. Menacé par les prédateurs introduits comme les hermines, furets et chats, sa survie dépend largement des programmes d'éradication de ces espèces invasives.",       "pictures/kiwi_brun",          2),
    ("Échidné à nez court","Tachyglossus aculeatus",   "Océanie", "Forêts",                      "Insectivore","0,4 m", "7 kg",    "50 ans", "L'un des cinq monotrèmes vivants – mammifères ovipares – l'échidné à nez court est recouvert de piquants creux en kératine comme le hérisson, mais n'y est pas du tout apparenté. Il n'a pas de dents et capture fourmis, termites et vers avec sa langue collante et filamenteuse pouvant s'allonger à 18 cm et effectuer 100 mouvements par minute. En cas de danger, il se roule en boule ou s'enfonce rapidement dans le sol en creusant verticalement pour ne présenter que ses piquants. La femelle pond un seul œuf directement dans sa poche marsupiale où il éclot. Le jeune, appelé puggle, est allaité par des patches de peau sécrétant du lait car l'échidné n'a pas de mamelons. Sa longévité exceptionnelle – jusqu'à 50 ans en captivité – est remarquable pour un animal de sa taille.",                    "pictures/echidne_nez_court",  2),
    ("Quokka",             "Setonix brachyurus",       "Océanie", "Forêts",                      "Herbivore", "0,5 m",  "4 kg",    "10 ans", "Petit marsupial herbivore endémique du sud-ouest de l'Australie et de l'île Rottnest, le quokka est devenu une sensation mondiale sur les réseaux sociaux grâce à son expression faciale souriante permanente, due à la courbure de ses lèvres, et à son tempérament curieux et peu craintif envers les humains. Ce comportement confiant, résultant de millénaires en l'absence de prédateurs sur son île, le rend très photogénique mais aussi vulnérable. Contrairement à leur apparence débonnaire, les quokkas sont capables, sous stress extrême, de jeter leur jeune hors de la poche pour distancer un prédateur. Herbivore broutant herbes, feuilles et tiges, il peut survivre de longues périodes sans eau, extrayant l'humidité de sa nourriture.",          "pictures/quokka",             2),
    ("Perroquet kéa",      "Nestor notabilis",         "Océanie", "Montagnes",                   "Omnivore",  "0,5 m",  "1 kg",    "20 ans", "Seul perroquet alpin au monde, le kéa de Nouvelle-Zélande est réputé pour son intelligence extraordinaire, comparable à celle d'un primate, et sa curiosité insatiable qui le pousse à démonter les équipements des campeurs, déchirer les essuie-glaces des voitures et explorer sans peur tout ce qui est nouveau. Des études ont démontré qu'il est capable de résoudre des problèmes complexes en plusieurs étapes, d'utiliser des outils et même de prendre des décisions probabilistes. Il vit dans les forêts de hêtres subalpins et les zones rocheuses au-dessus de la limite forestière. Son régime omnivore très varié inclut racines, baies, insectes et larves, mais aussi la graisse dorsale des moutons, comportement qui lui a valu des persécutions par les éleveurs. Classé en danger d'extinction.",       "pictures/perroquet_kea",      2),

    # ── ANTARCTIQUE (10) ──────────────────────────────────────────────────────
    ("Manchot empereur",   "Aptenodytes forsteri",     "Antarctique", "Glaciers / Banquise",     "Piscivore", "1,2 m",  "30 kg",   "20 ans", "Plus grand et plus lourd des manchots, le manchot empereur est le seul oiseau au monde à se reproduire pendant l'hiver antarctique, dans des conditions parmi les plus extrêmes de la planète : températures descendant à -60°C et vents soufflant à 200 km/h. Les mâles couvent seuls l'unique œuf sur leurs pattes, le recouvrant d'un repli abdominal chaud, se serrant en tortues rotatives pour partager la chaleur pendant deux mois, sans manger. Ils peuvent ainsi perdre jusqu'à 40 % de leur poids. Plongeur exceptionnel, il peut descendre à plus de 550 mètres de profondeur et rester sous l'eau jusqu'à 22 minutes pour chasser poissons et calmars. Ses os, denses et non creux, facilitent les plongées profondes au détriment du vol.",                      "pictures/manchot_empereur",   3),
    ("Manchot Adélie",     "Pygoscelis adeliae",       "Antarctique", "Glaciers / Banquise",     "Piscivore", "0,7 m",  "5 kg",    "11 ans", "Petit manchot énergique et combatif des côtes antarctiques, le manchot Adélie est l'un des manchots les plus communs et les plus étudiés de l'Antarctique. Il niche en grandes colonies bruyantes de plusieurs milliers de couples sur les zones rocheuses libres de glace. La construction du nid, constitué de galets soigneusement sélectionnés et arrangés pour évacuer l'eau de fonte, donne lieu à de véritables vols et batailles entre voisins. Les manchots Adélie nagent jusqu'à 300 km aller-retour pour pêcher des krill et des poissons. Leurs migrations marines hivernales, parcourant jusqu'à 17 000 km, ont été révélées grâce aux balises de suivi. Sensibles aux variations climatiques qui affectent l'étendue de la banquise et donc la disponibilité du krill.",      "pictures/manchot_adelie",     3),
    ("Phoque de Weddell",  "Leptonychotes weddellii",  "Antarctique", "Glaciers / Banquise",     "Piscivore", "2,5 m",  "450 kg",  "30 ans", "Mammifère marin vivant le plus au sud de tous les animaux à sang chaud, le phoque de Weddell passe une grande partie de l'hiver sous la banquise, maintenant ses trous de respiration ouverts en rongeant la glace avec ses dents incisives, ce qui entraîne une usure importante avec l'âge. Champion de la plongée parmi les mammifères, il peut descendre à plus de 700 mètres de profondeur et demeurer immergé jusqu'à 80 minutes pour chasser les poissons de fond et les calmars dans les eaux glacées. Son sang et ses muscles sont riches en myoglobine, pigment capable de stocker l'oxygène, lui donnant une teinte presque noire. Les femelles mettent bas directement sur la glace en septembre et octobre, allaitant leurs petits d'un lait extrêmement riche en graisses.",                  "pictures/phoque_weddell",     3),
    ("Éléphant de mer du Sud","Mirounga leonina",      "Antarctique", "Mer / Océan",             "Piscivore", "4,5 m",  "2200 kg", "20 ans", "Plus grand phoque et plus grand carnivore du monde, l'éléphant de mer du Sud présente l'un des dimorphismes sexuels les plus spectaculaires du règne animal : le mâle peut être 5 à 6 fois plus lourd que la femelle. La trompe gonflable du mâle, qui lui vaut son nom, amplifie ses rugissements lors des combats pour la possession des harems, pouvant regrouper plusieurs centaines de femelles. Ces batailles sont violentes et peuvent laisser des cicatrices profondes. Plongeur exceptionnel, il peut descendre à 1 500 mètres de profondeur et rester immergé jusqu'à 2 heures. Après la saison de reproduction, il effectue deux longues migrations annuelles en mer ouverte, parcourant des dizaines de milliers de kilomètres sans toucher terre.",           "pictures/elephant_mer_sud",   3),
    ("Orque",              "Orcinus orca",             "Antarctique", "Mer / Océan",             "Carnivore", "7,0 m",  "5500 kg", "60 ans", "Plus grand dauphin et apex prédateur des océans, l'orque ne connaît aucun prédateur naturel. Elle chasse en groupes familiaux très structurés appelés clans, utilisant des techniques de chasse sophistiquées et coordonnées transmises culturellement de génération en génération : échouage délibéré pour saisir des lions de mer sur la plage, vagues de chasse pour balayer des phoques de leur banquise, ou attaques synchronisées de baleines bleues. Chaque clan possède ses propres vocalisations dialectales distinctes. L'orque est l'un des très rares animaux non-humains à vivre après sa ménopause, les femelles âgées jouant un rôle de leadership crucial pour transmettre leur expérience et mémoire écologique au groupe. Elle est présente dans tous les océans du monde, des tropiques aux pôles.",                      "pictures/orque",              5),
    ("Léopard de mer",     "Hydrurga leptonyx",        "Antarctique", "Glaciers / Banquise",     "Carnivore", "3,5 m",  "500 kg",  "26 ans", "Prédateur solitaire et redoutable des eaux antarctiques, le léopard de mer est le deuxième plus grand phoque de l'Antarctique et l'un des rares à se nourrir activement de proies à sang chaud, notamment les manchots. Sa tête étonnamment grande, ses longues mâchoires et ses dents impressionnantes lui permettent de saisir et de dépouiller les manchots avec efficacité. Pour consommer les petits manchots, il les saisit et les secoue violemment jusqu'à retourner leur peau. Malgré son image de tueur, le krill constitue une part importante de son régime en dehors des saisons de reproduction des manchots. Sa gueule est également adaptée pour filtrer le krill de l'eau. Curieux et parfois agressif envers les plongeurs humains, il représente un risque réel sous la glace.",             "pictures/leopard_mer",        4),
    ("Albatros hurleur",   "Diomedea exulans",         "Antarctique", "Mer / Océan",             "Carnivore", "1,4 m",  "9 kg",    "60 ans", "Oiseau possédant la plus grande envergure du monde – jusqu'à 3,5 mètres – l'albatros hurleur est un planeur hors pair qui peut parcourir des milliers de kilomètres sans escale en utilisant une technique appelée vol dynamique : il exploite les différences de vitesse du vent entre la surface de l'eau et la hauteur pour se propulser en consommant presque zéro énergie, pouvant rester en vol pendant des années sans toucher terre. Il se nourrit principalement de calmars, poissons et charognes récupérés à la surface de l'eau la nuit. Il s'accouple pour la vie et revient au même site de nidification sur les îles subantarctiques chaque année.",   "pictures/albatros_hurleur",   3),
    ("Pétrel géant",       "Macronectes giganteus",    "Antarctique", "Mer / Océan",             "Carnivore", "1,0 m",  "5 kg",    "20 ans", "Grand oiseau marin des mers australes jouant un double rôle de charognard et de prédateur actif, le pétrel géant est parfois surnommé le vautour des mers. Il consomme des cadavres de phoques, manchots et baleines, dépeçant les carcasses à l'aide de son puissant bec crochu. Il chasse également activement de petits oiseaux marins, des poussins de manchots et attrape des poissons et calmars en surface. Son crâne et son bec sont tachés de sang après s'être nourri, contrairement aux albatros. Les deux sexes couvent l'unique œuf pendant environ 60 jours et partagent l'élevage du poussin. Ses effectifs peuvent être affectés par les interactions avec la pêche industrielle, notamment les lignes de palangre.",        "pictures/petrel_geant",       3),
    ("Manchot à jugulaire","Pygoscelis antarcticus",   "Antarctique", "Glaciers / Banquise",     "Piscivore", "0,7 m",  "4,5 kg",  "20 ans", "Manchot reconnaissable à la fine bande noire qui barre son menton comme une jugulaire de casque militaire, le manchot à jugulaire niche en colonies denses souvent situées sur des falaises rocheuses escarpées aux extrémités des péninsules antarctiques. Plongeur efficace jusqu'à 200 mètres de profondeur, il se nourrit principalement de krill qu'il filtre par groupes. Ses nids de galets sont construits sur des reliefs exposés et venteux pour éviter les accumulations de neige et l'inondation lors de la fonte. Les parents se relaient pour incuber les deux œufs et alimenter les poussins. Très vocal et agressif pour défendre son espace de nidification, il peut infliger des coups de bec et de nageoires douloureux. Sa population est estimée à plus de 7 millions d'individus.",             "pictures/manchot_jugulaire",  3),
    ("Crevette antarctique","Euphausia superba",       "Antarctique", "Mer / Océan",             "Détritivore","0,06 m","0,002 kg","5 ans", "Petite crevette bioluminescente formant la base de toute la chaîne alimentaire antarctique, le krill antarctique est l'un des animaux les plus abondants de la planète en termes de biomasse totale – estimée à 500 millions de tonnes – et constitue la ressource alimentaire principale des baleines à fanons, des manchots, des phoques, des albatros et d'innombrables autres espèces. En hiver, sous la banquise, il se nourrit des micro-algues qui colonisent la face inférieure de la glace. En été, il forme des essaims si denses que l'eau en paraît rouge depuis les bateaux. Il effectue des migrations verticales quotidiennes, remontant la nuit et descendant le jour pour éviter les prédateurs. La pêche industrielle intensive et la réduction de la banquise liée au réchauffement climatique menacent ses populations.",            "pictures/crevette_antarctique",1),

    # ── MOYEN-ORIENT (10) ─────────────────────────────────────────────────────
    ("Dromadaire",         "Camelus dromedarius",      "Moyen-Orient", "Désert",                 "Herbivore", "2,2 m",  "600 kg",  "25 ans", "Grand mammifère parfaitement adapté aux conditions les plus hostiles des déserts du Moyen-Orient et d'Afrique du Nord, le dromadaire stocke non pas de l'eau mais des réserves de graisses dans sa bosse caractéristique, qui peuvent atteindre 35 kg et lui fournir énergie et eau métabolique en période de pénurie. Il peut perdre jusqu'à 30 % de son poids en eau sans être mis en danger, une perte qui tuerait la plupart des mammifères, et reconstituer ses réserves en buvant 200 litres en quelques minutes. Ses narines en fente, ses longues cils doubles et ses sourcils proéminents le protègent du sable. Domestiqué depuis plus de 4 000 ans, il est indispensable aux peuples du désert comme animal de transport, source de lait, de viande et de laine.",                   "pictures/dromadaire",         2),
    ("Oryx d'Arabie",      "Oryx leucoryx",            "Moyen-Orient", "Désert",                 "Herbivore", "1,0 m",  "70 kg",   "20 ans", "Antilope blanche élancée et gracieuse parfaitement adaptée aux déserts arides de la péninsule arabique, l'oryx d'Arabie est capable de détecter les précipitations à longue distance grâce à un odorat très développé et de parcourir de grandes distances pour rejoindre des zones d'herbe fraîche après les rares pluies. Son pelage blanc réfléchit la chaleur et ses glandes nasales refroidissent l'air inspiré. Déclaré éteint à l'état sauvage en 1972, victime de la chasse intensive, il a bénéficié de l'un des premiers et des plus réussis programmes de réintroduction au monde : des individus issus de zoos américains ont été relâchés à Oman dès 1982, et les populations sauvages comptent aujourd'hui plusieurs milliers d'individus. Un symbole mondial de la conservation moderne.",                 "pictures/oryx_arabie",        2),
    ("Fennec",             "Vulpes zerda",             "Moyen-Orient", "Désert",                 "Omnivore",  "0,2 m",  "1,5 kg",  "10 ans", "Le plus petit canidé du monde, le fennec est immédiatement reconnaissable à ses oreilles démesurément grandes pouvant atteindre 15 cm, soit presque aussi longues que sa tête et son corps réunis. Ces oreilles géantes remplissent deux fonctions vitales : détecter les mouvements des proies sous le sable grâce à une ouïe extrêmement fine, et dissiper la chaleur corporelle par un réseau dense de vaisseaux sanguins superficiels. Ses pattes couvertes de poils épais lui permettent de courir sur le sable chaud sans se brûler, à la manière de raquettes. Omnivore opportuniste, il consomme insectes, lézards, petits rongeurs, fruits et œufs. Ses reins sont adaptés pour concentrer l'urine et minimiser les pertes d'eau. Il vit en couples monogames stables et creuse des terriers labyrinthiques dans le sable.",        "pictures/fennec",             3),
    ("Vipère à cornes",    "Cerastes cerastes",        "Moyen-Orient", "Désert",                 "Carnivore", "0,6 m",  "0,3 kg",  "15 ans", "Serpent venimeux des déserts sableux du Moyen-Orient et d'Afrique du Nord, la vipère à cornes doit son nom aux deux petites cornes situées au-dessus de ses yeux, dont la fonction reste débattue : elles pourraient réduire l'éblouissement du sable ou jouer un rôle dans la communication intra-spécifique. Elle se déplace par locomotion latérale typique des serpents des sables, ne laissant que des traces en J parallèles dans le sable. Elle s'enfouie dans le sable en quelques secondes pour réguler sa température, se dissimuler des prédateurs et tendre des embuscades aux lézards et rongeurs qui constituent sa proie. Crépusculaire et nocturne, elle évite les heures les plus chaudes de la journée. Son venin hémotoxique est dangereux pour l'homme mais les morsures mortelles sont rares.",      "pictures/vipere_cornes",      3),
    ("Guépard d'Asie",     "Acinonyx jubatus venaticus","Moyen-Orient","Steppe / Prairies tempérées","Carnivore","0,8 m","40 kg",  "12 ans", "Sous-espèce de guépard parmi les plus rares et menacées du monde, le guépard d'Asie, autrefois largement répandu de l'Arabie à l'Inde, est aujourd'hui réduit à une population estimée à moins de 50 individus survivant uniquement dans le désert de Kavir en Iran central. Son déclin catastrophique est dû à la persécution historique, à la capture pour la chasse à courre pratiquée par les cours royales, à la destruction de son habitat et à la raréfaction de ses proies. Malgré des tentatives de reproduction en captivité en Iran, aucun petit n'a encore survécu. Il est considéré par beaucoup comme l'animal le plus proche de l'extinction totale parmi les grands félins du monde. Des coopérations internationales tentent de le sauver, mais son avenir reste très incertain.",   "pictures/guepard_asie",       3),
    ("Ibis chauve",        "Geronticus eremita",       "Moyen-Orient", "Désert",                 "Insectivore","0,7 m", "1,2 kg",  "25 ans", "L'un des oiseaux les plus menacés au monde avec moins de 200 individus sauvages au Maroc et quelques couples rescapés en Syrie, l'ibis chauve est un grand oiseau migrateur des zones arides dont la tête et le cou nus, d'un rouge vif, contrastent avec son plumage noir irisé de reflets verts et violets. Il effectue des migrations saisonnières entre ses zones de nidification au Maroc et ses quartiers d'hiver en Éthiopie, volant en formations en V où les individus exploitent les turbulences générées par les battements d'ailes du voisin. Sa disparition d'Europe centrale il y a plusieurs siècles, où il nichait sur les falaises des Alpes et le long du Rhin, reste mysterieuse. Des programmes de réintroduction en Autriche, Italie et Espagne tentent de reconstituer des populations.",              "pictures/ibis_chauve",        2),
    ("Lézard agama",       "Agama stellio",            "Moyen-Orient", "Désert",                 "Insectivore","0,3 m", "0,07 kg", "5 ans",  "Lézard robuste et commun des zones rocheuses et semi-arides du Moyen-Orient et de la Méditerranée orientale, l'agama se distingue par sa capacité à changer de couleur selon son état émotionnel et sa température : le mâle dominant exhibe une tête bleue ou orange vif lors de la parade nuptiale ou de l'affrontement territorial, tandis qu'une coloration terne signale la soumission ou le froid. Il chasse les insectes, araignées et petits invertébrés à l'affût depuis des rochers en hauteur, se chauffant au soleil pour atteindre sa température active optimale. Territorial, le mâle défend son rocher par des hochements de tête rhythmiques et des pompes de pompes de bras. Plusieurs femelles peuvent partager son territoire.",       "pictures/lezard_agama",       2),
    ("Gazelle de montagne","Gazella gazella",          "Moyen-Orient", "Montagnes",              "Herbivore", "0,6 m",  "25 kg",   "12 ans", "Gazelle élancée et agile vivant dans les collines rocheuses et les pentes montagneuses du Levant – Israël, Jordanie, Liban – la gazelle de montagne est l'une des espèces les plus emblématiques de la faune du Proche-Orient. Elle se distingue par ses cornes légèrement annelées et incurvées, présentes chez les deux sexes. Sa vitesse de course et son agilité sur les terrains escarpés lui permettent d'échapper aux loups, léopards et aigles qui constituent ses prédateurs naturels. Active à l'aube et au crépuscule pour éviter les chaleurs de la journée, elle se nourrit de graminées, plantes herbacées et pousses de buissons. Sa population a fortement diminué en raison de la chasse, de l'expansion agricole et du braconnage, faisant l'objet de programmes de protection dans plusieurs pays de la région.",           "pictures/gazelle_montagne",   2),
    ("Hyène rayée",        "Hyaena hyaena",            "Moyen-Orient", "Désert",                 "Carnivore", "0,8 m",  "35 kg",   "20 ans", "Contrairement à sa cousine tachetée d'Afrique subsaharienne, la hyène rayée est un animal plutôt solitaire et farouche des déserts, steppes et zones montagneuses du Moyen-Orient, d'Asie centrale et d'Afrique du Nord. Charognard efficace, elle possède un système digestif exceptionnel capable de digérer os, dents, sabots et peau que les autres carnivores ne peuvent traiter, grâce à un suc gastrique particulièrement acide. Elle peut ramener des morceaux de carcasse dans son terrier et les enterrer comme réserve. Son pelage rayé et sa crinière dorsale qu'elle hérisse pour paraître plus grande en font un animal intimidant. Malgré sa mauvaise réputation, elle joue un rôle sanitaire fondamental dans son écosystème. Menacée par la perte d'habitat et la persécution humaine.",       "pictures/hyene_rayee",       3),
    ("Hérisson du désert", "Paraechinus aethiopicus",  "Moyen-Orient", "Désert",                 "Insectivore","0,2 m", "0,5 kg",  "7 ans",  "Petit hérisson insectivore nocturne parfaitement adapté aux déserts chauds et arides du Moyen-Orient et d'Afrique du Nord, le hérisson du désert supporte des températures extrêmes qui tueraient la plupart des autres mammifères. Il entre en estivation – l'équivalent estival de l'hibernation – pendant les périodes les plus chaudes et sèches de l'année. Ses grandes oreilles, comme celles du fennec, lui servent à dissiper la chaleur et à détecter les insectes, scorpions et petits lézards dont il se nourrit. Il est remarquablement résistant aux venins et peut consommer des scorpions et serpents venimeux sans en souffrir, grâce à des adaptations physiologiques de ses récepteurs neuromusculaires. Comme tous les hérissons, il se roule en boule en exposant ses piquants en cas de danger.",     "pictures/herisson_desert",    2),

    # ── ASIE DU SUD-EST (10) ──────────────────────────────────────────────────
    ("Orang-outan",        "Pongo pygmaeus",           "Asie du Sud-Est", "Forêt tropicale humide","Frugivore","1,2 m", "75 kg",   "30 ans", "Grand singe arboricole des forêts tropicales de Bornéo et Sumatra, l'orang-outan est notre cousin phylogénétique le plus proche parmi les grands singes asiatiques, partageant 97 % de notre ADN. Son nom signifie littéralement homme de la forêt en malais. Il construit chaque soir un nouveau nid de feuilles et de branches dans la canopée pour dormir. Solitaire par nature, les mâles adultes développent des excroissances charnues appelées coussinets faciaux qui signalent leur dominance et amplifient leurs longs appels caractéristiques portant à plusieurs kilomètres. Il utilise des outils – bâtons pour extraire des insectes, feuilles comme parasol – et transmet ces techniques culturellement. La déforestation massive pour les plantations d'huile de palme le mène directement à l'extinction.",       "pictures/orang_outan",        3),
    ("Tigre de Sumatra",   "Panthera tigris sumatrae", "Asie du Sud-Est", "Forêt tropicale humide","Carnivore","0,9 m", "130 kg",  "15 ans", "Plus petite sous-espèce de tigre encore existante, endémique de l'île de Sumatra en Indonésie, le tigre de Sumatra est aussi le dernier tigre insulaire au monde après la disparition du tigre de Bali en 1937 et du tigre de Java en 1980. Ses rayures plus serrées et plus foncées que celles des autres tigres lui confèrent un camouflage optimal dans la végétation dense de la forêt tropicale humide. Avec moins de 400 individus à l'état sauvage, il est l'une des espèces les plus menacées de la planète. La déforestation accélérée pour les plantations d'huile de palme et d'acacia détruit son habitat à une vitesse alarmante, tandis que le braconnage pour ses os et organes utilisés en médecine traditionnelle lui fait subir une pression supplémentaire.",           "pictures/tigre_sumatra",      4),
    ("Rhinocéros de Java", "Rhinoceros sondaicus",     "Asie du Sud-Est", "Forêt tropicale humide","Herbivore","1,6 m", "2000 kg", "35 ans", "Avec moins de 80 individus concentrés dans le seul parc national d'Ujung Kulon à la pointe occidentale de Java en Indonésie, le rhinocéros de Java est l'un des mammifères les plus menacés au monde, peut-être le plus proche de l'extinction parmi les grands mammifères. Il portait autrefois une seule corne pouvant atteindre 25 cm. Solitaire et extrêmement discret, il évite tout contact avec l'homme et c'est principalement grâce aux pièges photographiques que les chercheurs peuvent suivre les individus. Sa faible population, confinée dans un espace restreint, le rend particulièrement vulnérable aux catastrophes naturelles comme les éruptions du Krakatoa voisin. Toute la sous-espèce de Chine est éteinte depuis les années 1900.",           "pictures/rhinoceros_java",    2),
    ("Nasique",            "Nasalis larvatus",         "Asie du Sud-Est", "Marais / Mangroves",   "Folivore",  "0,7 m",  "22 kg",   "20 ans", "Primate endémique de l'île de Bornéo immédiatement reconnaissable au nez pendant et bulbeux des mâles adultes, qui peut dépasser 10 cm, le nasique est un singe de mangrove particulièrement habile à la nage, traversant régulièrement les rivières à la nage pour passer d'une zone de forêt à l'autre. Sa nez proéminent agit comme une caisse de résonance amplifiant ses appels d'alarme et de séduction, et constitue un signal honnête de bonne condition physique aux yeux des femelles. Son estomac chambré, proche de celui des ruminants, lui permet de digérer des feuilles contenant des tanins et des toxines que d'autres singes ne peuvent consommer. Le dévestissement des mangroves et des forêts alluviales de Bornéo pour l'agriculture et l'aquaculture menace directement ses populations.",                "pictures/nasique",            2),
    ("Varan de Komodo",    "Varanus komodoensis",      "Asie du Sud-Est", "Forêts",              "Carnivore", "2,5 m",  "70 kg",   "30 ans", "Plus grand lézard vivant au monde, endémique des îles indonésiennes de Komodo, Rinca, Flores et Gili Motang, le varan de Komodo est un prédateur redoutable dont la salive, longtemps crue simplement septique, contient en réalité des glandes à venin anticoagulant qui affaiblissent progressivement les proies mordues. Sa langue fourchue, comme celle des serpents, lui sert à détecter les odeurs sur plusieurs kilomètres. Capables d'avaler des proies entières allant jusqu'à 50 kg, il peut ingurgiter 80 % de son poids en un seul repas. Il peut se reproduire par parthénogenèse – sans mâle – et le ratio des naissances est alors biaisé vers les mâles. Sa vitesse de course peut atteindre 20 km/h sur de courtes distances.",         "pictures/varan_komodo",       4),
    ("Pangolin malais",    "Manis javanica",           "Asie du Sud-Est", "Forêts",              "Insectivore","0,6 m", "7 kg",    "13 ans", "Mammifère recouvert de grandes écailles imbriquées en kératine – le seul mammifère au monde dans cette situation – le pangolin malais ressemble à une pomme de pin géante ambulante. Ces écailles, composées exactement du même matériau que nos ongles, forment une armure redoutable quand il se roule en boule. Sa longue langue gluante, pouvant s'étendre à 25 cm au-delà de son museau, est idéale pour extraire fourmis et termites de leurs constructions. Il est tristement l'animal le plus braconné au monde en raison de la demande massive pour ses écailles utilisées en médecine traditionnelle asiatique et sa viande consommée comme mets de luxe. Les quatre espèces asiatiques et africaines sont toutes menacées, certaines en danger critique d'extinction.",           "pictures/pangolin_malais",    2),
    ("Tapir malais",       "Tapirus indicus",          "Asie du Sud-Est", "Forêt tropicale humide","Herbivore","1,0 m",  "300 kg",  "25 ans", "Plus grand tapir du monde et seul tapir de l'Ancien Monde, le tapir malais est reconnaissable à son patron bicolore saisissant – corps noir à l'avant et aux pattes, blanc au centre – qui brise efficacement sa silhouette dans la forêt sombre et constitue un excellent camouflage. Sa petite trompe préhensile lui permet de saisir branches et feuilles et de détecter les odeurs. Excellent nageur, il se réfugie fréquemment dans l'eau pour se rafraîchir et échapper aux prédateurs. Herbivore crépusculaire et nocturne, il se nourrit des végétaux qu'il trouve le long des cours d'eau et en forêt. Jouant le rôle de jardinier de la forêt en dispersant les graines, sa disparition affecterait la régénération de nombreuses espèces végétales. Classé en danger d'extinction du fait de la déforestation.",    "pictures/tapir_malais",       2),
    ("Python réticulé",    "Malayopython reticulatus", "Asie du Sud-Est", "Forêt tropicale humide","Carnivore","6,0 m",  "75 kg",   "20 ans", "Plus long serpent du monde – les plus grands spécimens documentés dépassant 7 mètres – le python réticulé est un constricteur non venimeux capable d'avaler des proies aussi grandes qu'un chevreuil, un porc ou, dans de rares cas, un être humain. Son nom vient du motif géométrique complexe et réticulé de ses écailles, aux nuances de brun, de jaune et de noir. Il chasse à l'affût, détectant la chaleur corporelle de ses proies grâce à des fosses labiales thermoréceptrices, les saisissant dans ses mâchoires avant de les étouffer par constriction progressive. Excellent nageur, il colonise aussi bien les forêts denses que les zones agricoles et les abords des villages. La femelle couve ses œufs en frissonnant pour élever la température de la ponte. Très recherché pour sa peau et la médecine traditionnelle.",      "pictures/python_reticule",    3),
    ("Calao rhinocéros",   "Buceros rhinoceros",       "Asie du Sud-Est", "Forêt tropicale humide","Frugivore","0,9 m",  "2,7 kg",  "35 ans", "Grand oiseau frugivore aux couleurs spectaculaires des forêts tropicales de la péninsule malaise, de Sumatra et de Bornéo, le calao rhinocéros est immédiatement reconnaissable au casque rouge et jaune qui surmonte son grand bec recourbé. Ce casque, appelé épicrâne, est une structure osseuse solide – contrairement à celui d'autres calaos creux – dont la fonction exacte reste débattue. La femelle se mure dans un creux d'arbre pour nidifier, l'entrée étant obstruée avec ses excréments, de l'argile et de la nourriture mâchée, n'y laissant qu'une fente par laquelle le mâle la nourrit pendant toute l'incubation et l'élevage des poussins. Il joue un rôle crucial de disperseur de graines dans la forêt. Emblème de l'État malaisien du Sarawak.",  "pictures/calao_rhinoceros",  2),
    ("Proboscis",          "Nasalis larvatus",         "Asie du Sud-Est", "Marais / Mangroves",  "Folivore",  "0,7 m",  "20 kg",   "20 ans", "Primate endémique de l'île de Bornéo vivant dans les forêts de mangroves, de tourbe et les forêts alluviales des bords de cours d'eau, le proboscis – nom anglais du nasique – est l'un des singes les plus menacés d'Asie. Sa population a chuté de plus de 60 % au cours des 40 dernières années en raison de la destruction massive des mangroves et des forêts riveraines pour les plantations, les crevetteries et le développement industriel. Ses groupes, composés d'un mâle avec plusieurs femelles et leurs jeunes, vivent et dorment dans les arbres au bord de l'eau, se laissant tomber à la surface si nécessaire pour fuir un danger. Il est un indicateur fiable de la santé des écosystèmes de mangrove, sa présence signalant des forêts encore intactes.",     "pictures/proboscis",          2),

    # ── CARAÏBES & AMÉRIQUE CENTRALE (10) ─────────────────────────────────────
    ("Iguane vert",        "Iguana iguana",            "Caraïbes & Amérique Centrale", "Forêts", "Herbivore", "1,5 m",  "7 kg",    "15 ans", "Reptile herbivore arboricole emblématique des forêts tropicales d'Amérique centrale et des Caraïbes, l'iguane vert est l'un des plus grands lézards des Amériques. Malgré sa silhouette imposante avec sa crête dorsale d'épines et son fanon gulaire pendant, il se nourrit presque exclusivement de feuilles, fleurs et fruits. Sa peau à écailles chagrinées et sa coloration verte ou brun-orange changent avec l'âge et la température. Il communique par hochements de tête codifiés. Excellent grimpeur aux griffes acérées, il vit dans la canopée mais se laisse tomber dans l'eau depuis plusieurs mètres de hauteur pour fuir les prédateurs. La femelle pond jusqu'à 70 œufs dans des terriers. Très apprécié comme animal de compagnie dans le monde entier, il est largement capturé et élevé mais son commerce est désormais réglementé.",                  "pictures/iguane_vert",        2),
    ("Quetzal resplendissant","Pharomachrus mocinno",  "Caraïbes & Amérique Centrale", "Forêts", "Frugivore", "0,4 m",  "0,2 kg",  "20 ans", "Considéré comme l'un des plus beaux oiseaux du monde, le quetzal resplendissant est l'oiseau national du Guatemala et était vénéré comme divinité par les civilisations maya et aztèque, qui utilisaient ses plumes dans les coiffures des souverains. Le mâle arbore une queue ornementale de plumes rectrices vert émeraude iridescent pouvant atteindre 60 cm, soit le double de la longueur de son corps. Il vit dans les forêts de nuages des montagnes d'Amérique centrale entre 1 500 et 3 000 mètres d'altitude, se nourrissant principalement d'avocats sauvages dont il avale le fruit entier et régurgite le noyau, contribuant ainsi à la dissémination de l'arbre. Menacé par la déforestation des forêts de nuages, il est classé quasi-menacé.",        "pictures/quetzal_resplendissant",2),
    ("Tapir de Baird",     "Tapirus bairdii",          "Caraïbes & Amérique Centrale", "Forêt tropicale humide","Herbivore","1,1 m","300 kg", "30 ans","Plus grand mammifère terrestre natif d'Amérique centrale, le tapir de Baird est un herbivore nocturne des forêts tropicales humides depuis le Mexique jusqu'au nord-ouest de la Colombie. Sa trompe préhensile, formée du nez et de la lèvre supérieure soudés et allongés, lui sert à atteindre et saisir les feuilles, fruits et brindilles à différentes hauteurs. Il est un puissant jardinier de la forêt : ses excréments contiennent des graines de dizaines d'espèces végétales dont il assure la dispersion sur de grandes distances. Excellent nageur, il traverse régulièrement les rivières et se réfugie dans l'eau pour fuir les jaguars et les pumas qui sont ses principaux prédateurs. Classé en danger d'extinction en raison de la chasse et de la déforestation accélérée en Amérique centrale.",              "pictures/tapir_baird",        2),
    ("Grenouille dart bleu","Dendrobates tinctorius", "Caraïbes & Amérique Centrale", "Forêt tropicale humide","Insectivore","0,04 m","0,003 kg","10 ans","Petite grenouille d'une beauté saisissante aux couleurs électriques – bleu vif, jaune, rouge ou orange selon les morphes – la grenouille dart ou dendrobate tire son nom du fait que les chasseurs amérindiens utilisaient son poison cutané pour enduire leurs sarbacanes. Sa coloration éclatante est un signal d'avertissement aposématique indiquant sa toxicité aux prédateurs potentiels. Le venin, des alcaloïdes dérivés des fourmis et insectes dont elle se nourrit dans la nature, disparaît en captivité où elle est nourrie d'insectes non toxiques. Les parents font preuve d'un soin parental élaboré : le mâle surveille les œufs, transporte les têtards sur son dos vers des microbiotopes aquatiques appropriés et vérifie leur progression. Menacée par la déforestation et le commerce illégal.",          "pictures/grenouille_dart_bleu",2),
    ("Lamentin des Caraïbes","Trichechus manatus",    "Caraïbes & Amérique Centrale", "Mer / Océan",          "Herbivore", "3,0 m",  "500 kg",  "40 ans", "Grand mammifère marin herbivore des côtes peu profondes, estuaires et rivières des Caraïbes et du golfe du Mexique, le lamentin des Caraïbes est surnommé la vache de mer en raison de son mode de vie paisible et de son régime végétarien composé de graminées marines, d'algues et de plantes aquatiques. Il consomme jusqu'à 10 % de son poids par jour. Sa peau ridée et épaisse est souvent couverte d'algues et de balanes. Il doit remonter à la surface toutes les 3 à 5 minutes pour respirer. Très vulnérable aux collisions avec les bateaux à moteur – la majorité des lamentins adultes portent des cicatrices d'hélices – et à la dégradation des herbiers marins, il est classé vulnérable. Sa mise à bas d'un seul petit tous les deux à trois ans ralentit considérablement la reconstitution des populations.",         "pictures/lamentin_caraibes",  2),
    ("Ara macao",          "Ara macao",                "Caraïbes & Amérique Centrale", "Forêt tropicale humide","Frugivore","0,9 m", "1 kg",    "50 ans", "Grand perroquet aux couleurs spectaculaires des forêts tropicales d'Amérique centrale et du Mexique, l'ara macao ou ara rouge est l'un des perroquets les plus grands et les plus colorés du monde, arborant un plumage rouge vif aux rémiges bleu vif et jaune d'or. Très intelligent, il est capable d'apprendre de nombreux mots et d'imiter des sons avec précision. Il vit en couples monogames stables qui demeurent souvent liés pour la vie, et niche dans les cavités des arbres morts ou des falaises. Son bec puissant courbe, parmi les plus robustes du règne aviaire, lui permet de briser les coques de noix les plus dures. Il se rassemble en grandes troupes bruyantes aux gîtes de couchage. Gravement menacé par la capture pour le commerce d'animaux de compagnie et la destruction de la forêt tropicale.",       "pictures/ara_macao",         2),
    ("Ocelot",             "Leopardus pardalis",       "Caraïbes & Amérique Centrale", "Forêts",              "Carnivore", "0,7 m",  "15 kg",   "13 ans", "Félin nocturne aux taches et rayures brun doré sur fond beige, l'ocelot est le plus grand des petits félins d'Amérique centrale et du Sud. Son pelage extraordinairement beau, évoquant celui d'un léopard miniature, lui a longtemps valu une chasse intensive pour la fourrure qui a décimé ses populations. Prédateur nocturne et solitaire, il chasse rongeurs, lézards, petits singes, oiseaux et serpents en progressant silencieusement dans la forêt. Ses sens de l'ouïe et de la vue sont très développés pour la chasse dans l'obscurité. Excellent grimpeur et nageur, il exploite tous les étages de la forêt tropicale. Sa densité de population dépend directement de la disponibilité des proies et de l'intégrité de la forêt. Désormais protégé, ses populations se reconstituent lentement dans certaines zones.",         "pictures/ocelot",             3),
    ("Tatou géant",        "Priodontes maximus",       "Caraïbes & Amérique Centrale", "Forêts",              "Insectivore","0,9 m", "30 kg",   "15 ans", "Plus grand tatou du monde, le tatou géant est recouvert d'une armure articulée de plaques osseuses et kératineuses appelées scutes qui lui permettent de se rouler en boule pour se protéger des prédateurs. Ses griffes antérieures, parmi les plus longues proportionnellement à la taille de tout mammifère, peuvent atteindre 20 cm et lui permettent d'ouvrir les termitières les plus dures. Sa langue extensible, recouverte de salive collante, capture fourmis et termites avec une rapidité foudroyante. Nocturne et solitaire, il est rarement observé à l'état sauvage malgré sa taille. Il creuse des terriers profonds qui, une fois abandonnés, sont utilisés par de nombreuses autres espèces. Menacé par la perte d'habitat et la chasse pour sa viande, il est classé vulnérable.",     "pictures/tatou_geant",        2),
    ("Boa constricteur",   "Boa constrictor",          "Caraïbes & Amérique Centrale", "Forêts",              "Carnivore", "3,0 m",  "15 kg",   "20 ans", "Serpent constricteur emblématique des forêts tropicales et zones arbustives des Caraïbes et d'Amérique centrale, le boa constricteur est un chasseur nocturne à l'affût qui détecte la chaleur de ses proies – oiseaux, rongeurs, lézards et petits mammifères – grâce à des fossettes labiales thermoréceptrices situées le long des lèvres. Après avoir saisi sa proie dans ses crochets non venimeux, il l'enroule dans ses anneaux musculeux et serre progressivement à chaque expiration de la victime jusqu'à arrêt cardiaque, puis l'avale entière. Ses mâchoires peuvent s'écarter considérablement grâce à un ligament élastique. La femelle est ovovivipare et donne naissance à des petits vivants pouvant être une vingtaine. Très apprécié comme animal de compagnie, son élevage est réglementé.",   "pictures/boa_constricteur",   3),
    ("Colibri d'Hélène",   "Mellisuga helenae",        "Caraïbes & Amérique Centrale", "Forêts",              "Nectarivore","0,06 m","0,002 kg","7 ans", "Plus petit oiseau du monde, endémique de Cuba et de l'île Isla de la Juventud, le colibri d'Hélène, ou colibri abeille, ne pèse que 1,6 gramme et mesure 5,7 cm du bout du bec à la queue. Son cœur bat jusqu'à 1 200 fois par minute à l'effort et ses ailes battent jusqu'à 80 fois par seconde, lui permettant de voler sur place et même à reculons pour butiner le nectar des fleurs. Pour survivre à la nuit, lorsque son métabolisme hyper-actif consommerait toutes ses réserves, il entre en torpeur, ralentissant son cœur à quelques battements par minute. Son bec et sa langue en tube sont précisément adaptés aux fleurs tubulaires spécifiques de son habitat cubain. Comme tous les colibris, il joue un rôle fondamental de pollinisateur dans les forêts tropicales.",                   "pictures/colibri_helene",     2),
]




def create_database():
    if os.path.exists(DB_NAME):
        os.remove(DB_NAME)

    conn = sqlite3.connect(DB_NAME)
    conn.execute("PRAGMA foreign_keys = ON;")
    cursor = conn.cursor()

    # --- Création des tables ---
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS Regions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nom_region TEXT UNIQUE,
            description TEXT
        );
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS Habitats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nom_habitat TEXT UNIQUE,
            description TEXT
        );
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS RegimesAlimentaires (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nom TEXT UNIQUE,
            description TEXT
        );
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS Especes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nom_commun TEXT NOT NULL,
            nom_scientifique TEXT,
            region_id INTEGER,
            habitat_id INTEGER,
            regime_id INTEGER,
            taille_moyenne TEXT,
            poids_moyen TEXT,
            esperance_vie TEXT,
            description TEXT,
            image_url TEXT,
            niveau_trophique INTEGER,
            FOREIGN KEY(region_id) REFERENCES Regions(id) ON UPDATE CASCADE ON DELETE SET NULL,
            FOREIGN KEY(habitat_id) REFERENCES Habitats(id) ON UPDATE CASCADE ON DELETE SET NULL,
            FOREIGN KEY(regime_id) REFERENCES RegimesAlimentaires(id) ON UPDATE CASCADE ON DELETE SET NULL
        );
    """)

    conn.commit()

    # --- Insertion des données ---
    for nom, desc in REGIONS:
        cursor.execute("INSERT OR IGNORE INTO Regions (nom_region, description) VALUES (?, ?);", (nom, desc))

    for nom, desc in HABITATS:
        cursor.execute("INSERT OR IGNORE INTO Habitats (nom_habitat, description) VALUES (?, ?);", (nom, desc))

    for nom, desc in REGIMES:
        cursor.execute("INSERT OR IGNORE INTO RegimesAlimentaires (nom, description) VALUES (?, ?);", (nom, desc))

    conn.commit()

    # --- Insertion des animaux ---
    for animal in ANIMAUX:
        nom_commun, nom_scientifique, region_nom, habitat_nom, regime_nom, taille, poids, esperance, description, image_url, trophique = animal

        cursor.execute("SELECT id FROM Regions WHERE nom_region = ?;", (region_nom,))
        region_id = cursor.fetchone()[0]

        cursor.execute("SELECT id FROM Habitats WHERE nom_habitat = ?;", (habitat_nom,))
        habitat_id = cursor.fetchone()[0]

        cursor.execute("SELECT id FROM RegimesAlimentaires WHERE nom = ?;", (regime_nom,))
        regime_id = cursor.fetchone()[0]

        cursor.execute("""
            INSERT INTO Especes (
                nom_commun, nom_scientifique, region_id, habitat_id, regime_id,
                taille_moyenne, poids_moyen, esperance_vie, description, image_url, niveau_trophique
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
        """, (nom_commun, nom_scientifique, region_id, habitat_id, regime_id, taille, poids, esperance, description, normalize_image_url(image_url), trophique))

    conn.commit()
    conn.close()
    print(f"Base créée avec succès : {len(ANIMAUX)} animaux insérés ({len(ANIMAUX)//10} par région).")


if __name__ == "__main__":
    create_database()
